# Standalone live system-test harness for forked_google_cloud_auth. It is
# excluded from the parent workspace because it enables native-only
# tokio/reqwest features that must not leak into workspace wasm builds.
[package]
name = "gcp-systest"
version = "0.1.0"
edition = "2021"

[dependencies]
google-cloud-auth = { path = "../google-cloud-auth", package = "forked_google_cloud_auth" }
reqwest = { version = "0.13.1", default-features = false, features = ["stream", "rustls", "json"] }
tokio = { version = "1.36", features = ["rt", "rt-multi-thread", "macros", "time", "fs"] }
async-trait = "0.1"
serde_json = { version = "1.0.113", features = ["arbitrary_precision", "preserve_order"] }

use anyhow::Result;

#[derive(Debug)]
pub struct Config {
    pub base_url: String,
    pub secret: Option<String>,
    pub project_id: Option<String>,
    pub sessions_id: String,
    pub stage: String,
    pub host_name: String,
    pub log_redaction_enabled: bool,
    pub log_redaction_placeholder: String,
    pub max_log_chunk_chars: usize,
}

fn default_base_url() -> String {
    "https://app.boundaryml.com/api".to_string()
}

fn default_redaction_placeholder() -> String {
    "<BAML_LOG_REDACTED>".to_string()
}

fn default_sessions_id() -> String {
    uuid::Uuid::new_v4().to_string()
}

fn default_stage() -> String {
    "development".to_string()
}

fn default_host_name() -> String {
    #[cfg(target_arch = "wasm32")]
    return "<browser>".to_string();

    #[cfg(not(target_arch = "wasm32"))]
    hostname::get()
        .map(|h| h.to_string_lossy().to_string())
        .unwrap_or("unknown".to_string())
}

fn default_max_log_chunk_chars() -> usize {
    64_000
}

impl Config {
    pub fn from_env_vars<T: AsRef<str>>(env_vars: impl Iterator<Item = (T, T)>) -> Result<Self> {
        // Mirror `envy::prefixed("BOUNDARY_")`: keep only BOUNDARY_-prefixed keys,
        // strip the prefix, and lowercase the remainder to match field names.
        let map: std::collections::HashMap<String, String> = env_vars
            .filter_map(|(k, v)| {
                k.as_ref()
                    .strip_prefix("BOUNDARY_")
                    .map(|rest| (rest.to_ascii_lowercase(), v.as_ref().to_string()))
            })
            .collect();

        let get = |k: &str| map.get(k).cloned();

        fn parse_field<T>(key: &str, raw: &str) -> Result<T>
        where
            T: std::str::FromStr,
            T::Err: std::fmt::Display,
        {
            raw.parse::<T>().map_err(|e| {
                anyhow::anyhow!(
                    "Failed to parse config from environment variables: BOUNDARY_{}: {e}",
                    key.to_ascii_uppercase()
                )
            })
        }

        let config = Config {
            base_url: get("base_url").unwrap_or_else(default_base_url),
            secret: get("secret"),
            project_id: get("project_id"),
            sessions_id: get("sessions_id").unwrap_or_else(default_sessions_id),
            stage: get("stage").unwrap_or_else(default_stage),
            host_name: get("host_name").unwrap_or_else(default_host_name),
            log_redaction_enabled: match get("log_redaction_enabled") {
                Some(s) => parse_field("log_redaction_enabled", &s)?,
                None => false,
            },
            log_redaction_placeholder: get("log_redaction_placeholder")
                .unwrap_or_else(default_redaction_placeholder),
            max_log_chunk_chars: match get("max_log_chunk_chars") {
                Some(s) => parse_field("max_log_chunk_chars", &s)?,
                None => default_max_log_chunk_chars(),
            },
        };

        Ok(config.normalize())
    }

    pub fn normalize(mut self) -> Self {
        if self.base_url.is_empty() {
            self.base_url = default_base_url();
        }
        if self.sessions_id.is_empty() {
            self.sessions_id = default_sessions_id();
        }
        if self.stage.is_empty() {
            self.stage = default_stage();
        }
        if self.host_name.is_empty() {
            self.host_name = default_host_name();
        }
        if self.log_redaction_placeholder.is_empty() {
            self.log_redaction_placeholder = default_redaction_placeholder();
        }
        // max_log_chunk_chars is usize, so no need to check for empty string
        self
    }
}

# Codegen for the `sdk_tests/crates/<generator>/` crates: it discovers
# fixtures, compiles each through the full compiler, runs the language
# generator, and installs the result into `<fixture>/generated/`.
#
# The `[[bin]]` is the entry point a generator crate's `setup.sh` runs
# before its tests. Because it is a normal binary — not a build script —
# `cargo check` and `cargo clippy` only *check* this crate and its
# compiler/sdkgen closure instead of building it, and nothing regenerates
# during an ordinary workspace build.
#
# The `[lib]` holds the per-generator modules plus the shared fixture
# loader, so the generators stay unit-testable and the binary stays a thin
# CLI over them.
#
# Test-side glue (run_test_cmd, the per-generator `test_suite!()` macros)
# lives in the sibling `sdk_test_harness_runner` crate, which each
# generator crate wires in as a `[dev-dependencies]`.
#
# Package named `sdk_test_*` so cargo-stow's
# `ignore_crates = ["sdk_test_*"]` rule (see baml_language/stow.toml)
# covers it; the folder name stays short.
[package]
name = "sdk_test_codegen"
version = "0.1.0"
edition = "2021"
publish = false

[lib]
path = "src/lib.rs"

[[bin]]
name = "sdk_test_codegen"
path = "src/main.rs"

[dependencies]
# The shared fixture table lives in the runner so the codegen side and the
# test side cannot disagree about the corpus. It is std-only, so this costs
# one tiny unit and cannot cycle back.
sdk_test_harness_runner = { path = "../harness_runner" }
baml_artifact = { workspace = true }
baml_version = { workspace = true }
sdkgen_cpp = { workspace = true }
sdkgen_csharp = { workspace = true }
sdkgen_python_pydantic2 = { workspace = true }
sdkgen_swift = { workspace = true }
sdkgen_go = { workspace = true }
sdkgen_typescript_shared = { workspace = true }
sdkgen_java = { workspace = true }
sdkgen_rust = { workspace = true }
baml_codegen_types = { workspace = true }
baml_type = { workspace = true }
baml_base = { workspace = true }
baml_db = { workspace = true }
baml_ide = { workspace = true }
proc-macro2 = { workspace = true }
quote = { workspace = true }

[package.metadata.ci]
wasm_support = false

import '@testing-library/jest-dom/vitest';
import { beforeAll } from 'vitest';

// Initialize WASM before tests run
// In browser mode, fetch works natively so no patching needed
beforeAll(async () => {
  const initWasm = (await import('@b/bridge_wasm')).default;
  await initWasm();
});

[package]
name = "sdk_test_csharp"
version = "0.1.0"
edition = "2021"
publish = false

[dependencies]
base64 = { workspace = true }
bex_project = { workspace = true }
bridge_ctypes = { workspace = true }
indexmap = { workspace = true }
prost = { workspace = true }


[package.metadata.ci]
wasm_support = false
